entries[273329] = { ["name"] = "Premier Lieutenant Commander's Luminous Gloves", ["text"] = "Binds when picked up\nHands Plate\n461 Armor\n+28 Stamina\n+12 Intellect\nClasses: Paladin\nRequires Level 60\nEquip: Increases healing done by up to 25 and damage done by up to 7 for all magical spells and effects.\n\nEquip: Increases the critical strike chance of your Flash of Light by 2%.\n\nField Marshal's Aegis (0/6)\nPremier Lieutenant Commander's Luminous Gloves\nPremier Knight-Champion's Luminous Boots\nPremier Marshal's Luminous Legplates\nPremier Field Marshal's Luminous Chestplate\nPremier Marshal's Luminous Pauldrons\nPremier Field Marshal's Luminous Faceguard\n(2) Set : +20 Stamina.\n(3) Set : Reduces the cooldown of your Hammer of Justice by 10 sec.\n(6) Set : Increases healing done by up to 44 and damage done by up to 15 for all magical spells and effects." }
