entries[274029] = { ["name"] = "Ornate Shackle Key", ["text"] = "Quest Item\nUnique\n\"The Questioner had a variety of keys on his person, but this one is particularly ornate.\"" }
entries[274030] = { ["name"] = "Malleable Essence of Nature", ["text"] = "Crafting Reagent\n\"Acquired from disenchanting items from Hyjal Summit or Barrow Deeps. Its power can be harnessed in the creation of powerful crafted items.\"" }
entries[274035] = { ["name"] = "Staghide Drape", ["text"] = "Binds when picked up\nBack\n37 Armor\n+7 Agility\n+7 Stamina\n+8 Spirit\nSell Price:" }
entries[274041] = { ["name"] = "Document Box", ["text"] = "Unique\n\"A strange collection of maps, pictures, and official-looking documents. This might be worth a bit of gold at a merchant... or it might be worth a lot more to the right person.\"\nSell Price:" }
entries[274042] = { ["name"] = "Skullduggery Belt", ["text"] = "Binds when picked up\nWaist Leather\n62 Armor\n+7 Spirit\nRequires Level 29\nEquip: + 16 Attack Power.\n\nEquip: Increases your effective stealth level by 1.\nSell Price:" }
