entries[274048] = { ["name"] = "9-60 Battery Pack", ["text"] = "Requires Level 29\n\nUse: Restore 3 charges to a Manual Crowd Pummeler device in your possession. (5 Sec Cooldown)\nSell Price:" }
entries[274049] = { ["name"] = "Schematic: 9-60 Battery Pack", ["text"] = "Binds when picked up\nRequires Engineering (125)\n\"Teaches you how to make a 9-60 Battery Pack.\"" }
entries[274068] = { ["name"] = "Thermaplugg Medal of Honor", ["text"] = "Binds when picked up\nNeck\n+6 Stamina\n+6 Spirit\nRequires Level 29\nEquip: + 10 Attack Power.\n\"Azeroth's Best Pummeler\"\nSell Price:" }
