entries[274151] = { ["name"] = "Tender Nightsaber Haunch", ["text"] = "Binds when picked up\nUnique\nDuration: 1 hour\nUse: Place on the hills along the north-western ridge of the summit." }
entries[274152] = { ["name"] = "Roogug's Severed Head", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+6 Spirit\nRequires Level 25\nUse: Raise the severed head of Roogug, Horrifying and Silencing all Swine within 15 yds for 5 sec. (5 Min Cooldown)\nSell Price:" }
