entries[274176] = { ["name"] = "Premier Scalemail Walkers", ["text"] = "Binds when picked up\nFeet Mail\n244 Armor\n+19 Stamina\n+10 Intellect\nClasses: Shaman\nRequires Level 55\nEquip: Improves your chance to get a critical strike by 0.5%.\nEquip: Increases damage and healing done by magical spells and effects by up to 6 .\n\nEquip: Increases the speed of your Ghost Wolf ability by 15%.\n\nLieutenant Commander's Thunderfist (0/6)\nPremier Scalemail Vices\nPremier Scalemail Walkers\nPremier Scalemail Legguards\nPremier Scalemail Chestpiece\nPremier Scalemail Pauldrons\nPremier Scalemail Helm\n(2) Set : Increases damage and healing done by magical spells and effects by up to 23.\n(4) Set : Improves your chance to get a critical strike with all Shock spells by 2%.\n(6) Set : +20 Stamina." }
